<body>
  <div id="app"></div>

  <script>
    const featuredProducts = [
      { name: "The Meridian Jacket", category: "Outerwear", price: "$248", badge: "Best seller", tone: "#d8cec0" },
      { name: "Atlas Runner", category: "Footwear", price: "$148", badge: "New arrival", tone: "#cfdde0" },
      { name: "Canvas Carryall", category: "Accessories", price: "$96", badge: "Staff pick", tone: "#e4d5c8" },
      { name: "Studio Knit Set", category: "Apparel", price: "$164", badge: "Limited", tone: "#d7dfd2" }
    ];

    const deals = [
      {
        title: "Spring refresh",
        copy: "Up to 30% off elevated essentials built for everyday wear.",
        cta: "Shop the sale",
        alt: false
      },
      {
        title: "Bundle & save",
        copy: "Mix accessories and home goods to unlock extra savings at checkout.",
        cta: "Build a bundle",
        alt: true
      }
    ];

    const editorials = [
      {
        title: "Inside the capsule: neutral layers that work year-round",
        category: "Style edit",
        copy: "A closer look at lightweight tailoring, texture, and the pieces our stylists are pairing this season."
      },
      {
        title: "How to build a smarter weekend wardrobe",
        category: "Guide",
        copy: "Three easy formulas for travel, city errands, and everything in between."
      },
      {
        title: "From studio to street: an accessories forecast",
        category: "Journal",
        copy: "The tactile finishes and practical details defining modern retail collections."
      }
    ];

    function svgProduct(label, tone) {
      return `
        <svg viewBox="0 0 240 240" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${label}">
          <rect width="240" height="240" rx="30" fill="${tone}"/>
          <rect x="42" y="54" width="156" height="132" rx="28" fill="#ffffff" opacity="0.82"/>
          <path d="M78 108c18-24 39-36 42-36 10 0 9 18 25 18 13 0 16-13 28-13 12 0 20 9 29 31l14 36H63l15-36Z" fill="#1f6f8b" opacity="0.18"/>
          <circle cx="92" cy="88" r="10" fill="#d97757" opacity="0.75"/>
        </svg>`;
    }

    function Header() {
      return `
        <header class="topbar">
          <div class="brand">
            <div class="brand-mark">N</div>
            <div>Northstar Retail</div>
          </div>
          <nav class="nav" aria-label="Primary">
            <a href="#featured">Featured</a>
            <a href="#deals">Deals</a>
            <a href="#journal">Journal</a>
          </nav>
          <a class="pill" href="#featured">Shop new season</a>
        </header>`;
    }

    function Hero() {
      return `
        <section class="hero">
          <div class="hero-copy">
            <div class="eyebrow">Modern retail for everyday living</div>
            <div>
              <h1>Products, stories, and deals in one clean storefront.</h1>
              <p style="margin-top: 18px;">
                Discover elevated essentials, limited-time offers, and editorial picks curated to feel premium,
                useful, and easy to shop.
              </p>
            </div>
            <div class="hero-actions">
              <a class="btn btn-primary" href="#featured">Shop featured</a>
              <a class="btn btn-secondary" href="#journal">Read the journal</a>
            </div>
            <div class="stats" aria-label="Store highlights">
              <div class="stat"><strong>120+</strong><span class="muted">New arrivals this month</span></div>
              <div class="stat"><strong>4.9/5</strong><span class="muted">Average customer rating</span></div>
              <div class="stat"><strong>Free</strong><span class="muted">Shipping over $75</span></div>
            </div>
          </div>
          <div class="hero-visual">
            <div class="showcase">
              <div class="showcase-card">
                <div class="tag" style="background: rgba(255,255,255,0.18); color: #fff;">Featured edit</div>
                <h2 style="margin-top: 14px; font-size: 2rem; line-height: 1.05; letter-spacing: -0.04em;">Seasonal layers designed to mix, match, and repeat.</h2>
              </div>
            </div>
            <div class="mini-grid">
              <div class="mini-card">
                <div class="tag">New drop</div>
                <h3 style="margin-top: 12px;">Earth-toned essentials with polished texture.</h3>
              </div>
              <div class="mini-card">
                <div class="tag">Fast pickup</div>
                <h3 style="margin-top: 12px;">Same-day store availability in select cities.</h3>
              </div>
            </div>
          </div>
        </section>`;
    }

    function ProductCard(product) {
      return `
        <article class="product-card">
          <div class="product-image">${svgProduct(product.name, product.tone)}</div>
          <div class="product-body">
            <div class="tag">${product.badge}</div>
            <div>
              <h3>${product.name}</h3>
              <div class="product-meta" style="margin-top: 6px;">
                <span>${product.category}</span>
                <span class="price">${product.price}</span>
              </div>
            </div>
          </div>
        </article>`;
    }

    function DealCard(deal) {
      return `
        <article class="deal-card${deal.alt ? ' alt' : ''}">
          <div class="deal-copy">
            <div class="deal-badge">Limited-time offer</div>
            <h3 style="font-size: 1.8rem; letter-spacing: -0.03em;">${deal.title}</h3>
            <p style="max-width: 42ch; color: rgba(255,255,255,0.85);">${deal.copy}</p>
            <a class="btn btn-secondary" href="#featured" style="background: rgba(255,255,255,0.12); color: #fff; border-color: rgba(255,255,255,0.18); width: fit-content;">${deal.cta}</a>
          </div>
          <div class="deal-art" aria-hidden="true">
            <div style="font-size: 3rem;">%</div>
          </div>
        </article>`;
    }

    function EditorialCard(item) {
      return `
        <article class="editorial-card">
          <div class="editorial-image"></div>
          <div class="editorial-body">
            <div class="tag">${item.category}</div>
            <h3>${item.title}</h3>
            <p style="color: var(--muted);">${item.copy}</p>
          </div>
        </article>`;
    }

    function App() {
      return `
        <main class="page">
          ${Header()}
          ${Hero()}

          <section class="section" id="featured">
            <div class="section-head">
              <div>
                <div class="eyebrow">Featured products</div>
                <h2 style="margin-top: 10px; font-size: clamp(1.8rem, 3vw, 2.6rem); letter-spacing: -0.04em;">Curated essentials with a premium feel</h2>
              </div>
              <p>High-contrast photography, clear pricing, and clean spacing make the products easy to scan and shop.</p>
            </div>
            <div class="cards">
              ${featuredProducts.map(ProductCard).join("")}
            </div>
          </section>

          <section class="section" id="deals">
            <div class="section-head">
              <div>
                <div class="eyebrow">Deals</div>
                <h2 style="margin-top: 10px; font-size: clamp(1.8rem, 3vw, 2.6rem); letter-spacing: -0.04em;">Promotions that feel editorial, not noisy</h2>
              </div>
              <p>Use full-width offer blocks to spotlight sales without breaking the calm product-first layout.</p>
            </div>
            <div class="cards">
              ${deals.map(DealCard).join("")}
            </div>
          </section>

          <section class="section" id="journal">
            <div class="section-head">
              <div>
                <div class="eyebrow">Editorial content</div>
                <h2 style="margin-top: 10px; font-size: clamp(1.8rem, 3vw, 2.6rem); letter-spacing: -0.04em;">Stories that support discovery and brand tone</h2>
              </div>
              <p>Editorial cards add context, increase dwell time, and give the homepage a more modern retail identity.</p>
            </div>
            <div class="cards">
              ${editorials.map(EditorialCard).join("")}
            </div>
          </section>

          <footer class="footer">
            <div><strong>Northstar Retail</strong> — modern essentials, styled to shop.</div>
            <div>Designed as a standalone HTML document with React-style components in plain JavaScript.</div>
          </footer>
        </main>`;
    }

    document.getElementById("app").innerHTML = App();
  </script>
</body>
</html>
